function validate([s1, s2]) {
  for (const [name, s] of [['s1', s1], ['s2', s2]]) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 40) return `${name} needs 1 to 40 characters.`;
    if (!/^[a-z1-9]+$/.test(s)) return `${name} may contain only lowercase letters and the digits 1-9.`;
    if (/[1-9]{4}/.test(s)) return `${name} may not have more than 3 digits in a row.`;
  }
  return null;
}

