function possiblyEquals(s1, s2) {
  // Expand each encoded string into every pattern it can stand for, with '?' for an unknown letter.
  const expand = (s) => {
    let patterns = [''];
    let i = 0;
    while (i < s.length) {
      if (s[i] >= 'a' && s[i] <= 'z') { patterns = patterns.map(p => p + s[i]); i++; continue; }
      let end = i;
      while (end < s.length && s[end] >= '1' && s[end] <= '9') end++;
      const sums = new Set();
      const split = (rest, total) => {
        if (rest === '') { sums.add(total); return; }
        for (let cut = 1; cut <= rest.length; cut++) split(rest.slice(cut), total + Number(rest.slice(0, cut)));
      };
      split(s.slice(i, end), 0);
      patterns = patterns.flatMap(p => [...sums].map(t => p + '?'.repeat(t)));
      i = end;
    }
    return patterns;
  };
  const fits = (a, b) => {
    if (a.length !== b.length) return false;
    for (let k = 0; k < a.length; k++) if (a[k] !== '?' && b[k] !== '?' && a[k] !== b[k]) return false;
    return true;
  };
  const first = expand(s1), second = expand(s2);
  return first.some(a => second.some(b => fits(a, b)));
}

