function generate(rand, size) {
  const pick = (chars) => chars[Math.floor(rand() * chars.length)];
  const valid = (s) => s.length >= 1 && s.length <= 40 && !/[1-9]{4}/.test(s);
  // Encode an original string: replace random pieces by their lengths, keep other letters as they are.
  const encode = (original, maxPiece, replaceRate) => {
    let out = '', run = 0, pos = 0;
    while (pos < original.length) {
      const len = 1 + Math.floor(rand() * Math.min(maxPiece, original.length - pos));
      const digits = String(len);
      if (rand() < replaceRate && !digits.includes('0') && run + digits.length <= 3) { out += digits; run += digits.length; pos += len; }
      else { out += original[pos]; run = 0; pos += 1; }
    }
    return out;
  };
  const flipLetter = (s) => {
    const spots = [...s].map((c, k) => (c >= 'a' && c <= 'z' ? k : -1)).filter(k => k >= 0);
    if (!spots.length) return s + 'a';
    const k = spots[Math.floor(rand() * spots.length)];
    return s.slice(0, k) + (s[k] === 'a' ? 'b' : 'a') + s.slice(k + 1);
  };
  for (;;) {
    let s1, s2;
    if (size === 'small') {
      if (rand() < 0.4) {
        const make = () => Array.from({ length: 1 + Math.floor(rand() * 6) }, () => (rand() < 0.55 ? pick('ab') : pick(rand() < 0.85 ? '1234' : '123456789'))).join('');
        s1 = make();
        s2 = make();
      } else {
        const original = Array.from({ length: 1 + Math.floor(rand() * 10) }, () => pick('ab')).join('');
        s1 = encode(original, 6, 0.5);
        s2 = encode(original, 6, 0.5);
        if (rand() < 0.3) s2 = flipLetter(s2);
      }
    } else {
      const original = Array.from({ length: 100 + Math.floor(rand() * 500) }, () => pick(rand() < 0.7 ? 'a' : 'ab')).join('');
      s1 = encode(original, 120, 0.85);
      s2 = encode(original, 120, 0.85);
      if (rand() < 0.5) {
        const at = Math.floor(rand() * (s2.length + 1));
        s2 = rand() < 0.5 ? flipLetter(s2) : s2.slice(0, at) + pick('ab') + s2.slice(at);
      }
    }
    if (valid(s1) && valid(s2)) return [s1, s2];
  }
}
